-- 0002_outbox: the transactional outbox.
--
-- Events are written here in the same transaction as the products and variants
-- they describe, and the relay in cmd/server publishes them to Kafka afterwards.
-- That is what makes "the product exists" and "the read model will hear about
-- the product" a single fact rather than two writes that can disagree.
--
-- The topic is stored per row instead of being implied by the table, so a future
-- event stream does not need a schema change.
CREATE TABLE IF NOT EXISTS outbox_events (
    id             BIGSERIAL PRIMARY KEY,
    -- Generated by the database so the producer needs no uuid dependency. It
    -- travels to the consumer as the message key in the envelope, which is what
    -- lets a consumer recognise a redelivery of one event rather than two.
    event_id       UUID        NOT NULL UNIQUE,
    topic          TEXT        NOT NULL,
    event_type     TEXT        NOT NULL,
    aggregate_type TEXT        NOT NULL,
    aggregate_id   BIGINT      NOT NULL,
    -- The Kafka message key, stored explicitly because it is not always the
    -- aggregate id. Partition assignment must be reproducible across relays.
    partition_key  TEXT        NOT NULL,
    payload        JSONB       NOT NULL,

    occurred_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    published_at   TIMESTAMPTZ,
    failed_at      TIMESTAMPTZ,

    attempts       INTEGER     NOT NULL DEFAULT 0,
    -- Pushed out on failure so a struggling broker is not hammered, and so a
    -- row that has given up stops being claimed.
    next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Marks a row as taken by a relay for a bounded time. The claim is a single
    -- statement, so the lease rather than a held row lock is what stops a second
    -- relay from publishing the same event.
    leased_until   TIMESTAMPTZ,
    last_error     TEXT,

    CONSTRAINT outbox_events_attempts_non_negative CHECK (attempts >= 0)
);

-- Partial index over unpublished rows only. The relay's claim query is the hot
-- path and it only ever looks at pending work, so indexing every historical row
-- would grow the index without making that query any faster.
CREATE INDEX IF NOT EXISTS idx_outbox_pending
    ON outbox_events (next_attempt_at, id)
    WHERE published_at IS NULL AND failed_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_outbox_aggregate
    ON outbox_events (aggregate_type, aggregate_id);

-- Wake the relay the moment a row becomes visible instead of waiting for the
-- next poll. NOTIFY is transactional in PostgreSQL, so a rolled back write never
-- produces a notification.
--
-- The relay still polls on a timer: notifications are transient and are lost if
-- the relay is disconnected, so this is a latency optimisation and never the
-- transport. The payload is the row id, which keeps it far below the 8000 byte
-- limit, and identical notifications within one transaction collapse into one.
CREATE OR REPLACE FUNCTION outbox_events_notify()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM pg_notify('outbox_events', NEW.id::TEXT);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS outbox_events_notify_trigger ON outbox_events;
CREATE TRIGGER outbox_events_notify_trigger
    AFTER INSERT ON outbox_events
    FOR EACH ROW EXECUTE FUNCTION outbox_events_notify();
